/** Material Symbols use a 960 × 960 viewport shifted up by 960 (viewBox "0 -960 960 960"). */
private fun symbol(name: String, pathData: String): ImageVector =
    ImageVector.Builder(
        name = name,
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 960f,
        viewportHeight = 960f,
    ).apply {
        addGroup(translationY = 960f)
        addPath(pathData = addPathNodes(pathData), fill = SolidColor(Color.Black))
        clearGroup()
    }.build()
